import heapq

def match(orders):
    trades = []
    book = {}  # id -> dict(side, price, qty, seq, active)
    buy_heap = []  # (-price, seq, id)
    sell_heap = []  # (price, seq, id)
    seq_counter = 0

    def clean_buy():
        while buy_heap:
            negprice, seq, oid = buy_heap[0]
            info = book.get(oid)
            if info is None or not info['active'] or info['qty'] <= 0 or info['side'] != 'buy':
                heapq.heappop(buy_heap)
                continue
            break

    def clean_sell():
        while sell_heap:
            price, seq, oid = sell_heap[0]
            info = book.get(oid)
            if info is None or not info['active'] or info['qty'] <= 0 or info['side'] != 'sell':
                heapq.heappop(sell_heap)
                continue
            break

    for order in orders:
        typ = order[0]
        if typ == 'cancel':
            oid = order[1]
            info = book.get(oid)
            if info is not None and info['active'] and info['qty'] > 0:
                info['active'] = False
            continue

        if typ == 'limit':
            _, oid, side, price, qty = order
        elif typ == 'ioc':
            _, oid, side, price, qty = order
        elif typ == 'market':
            _, oid, side, qty = order
            price = None
        else:
            continue

        remaining = qty

        if side == 'buy':
            # match against sells
            while remaining > 0:
                clean_sell()
                if not sell_heap:
                    break
                sprice, sseq, soid = sell_heap[0]
                if typ != 'market' and sprice > price:
                    break
                sinfo = book[soid]
                trade_qty = min(remaining, sinfo['qty'])
                trades.append([oid, soid, sprice, trade_qty])
                remaining -= trade_qty
                sinfo['qty'] -= trade_qty
                if sinfo['qty'] <= 0:
                    sinfo['active'] = False
                    heapq.heappop(sell_heap)
            if typ == 'limit' and remaining > 0:
                info = {'side': 'buy', 'price': price, 'qty': remaining, 'seq': seq_counter, 'active': True}
                book[oid] = info
                heapq.heappush(buy_heap, (-price, seq_counter, oid))
                seq_counter += 1
            else:
                # if ioc/market fully or partially filled but there's leftover order id tracking not needed
                # still record book entry for cancel purposes only if limit; else discard
                if typ == 'limit':
                    pass
                seq_counter += 1
        else:  # side == 'sell'
            while remaining > 0:
                clean_buy()
                if not buy_heap:
                    break
                negprice, bseq, boid = buy_heap[0]
                bprice = -negprice
                if typ != 'market' and bprice < price:
                    break
                binfo = book[boid]
                trade_qty = min(remaining, binfo['qty'])
                trades.append([boid, oid, bprice, trade_qty])
                remaining -= trade_qty
                binfo['qty'] -= trade_qty
                if binfo['qty'] <= 0:
                    binfo['active'] = False
                    heapq.heappop(buy_heap)
            if typ == 'limit' and remaining > 0:
                info = {'side': 'sell', 'price': price, 'qty': remaining, 'seq': seq_counter, 'active': True}
                book[oid] = info
                heapq.heappush(sell_heap, (price, seq_counter, oid))
                seq_counter += 1
            else:
                if typ == 'limit':
                    pass
                seq_counter += 1

    return trades

